from __future__ import annotations

from datetime import date
import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class CrossSectionalMomentum(Strategy):
    rationale = (
        "Cross-sectional momentum exploits the tendency of high-momentum stocks to continue "
        "outperforming low-momentum stocks over time. This strategy identifies top performers "
        "based on recent price gains and allocates capital accordingly."
    )

    def __init__(self, window: int = 20, top_n: int = 5) -> None:
        self._window = window
        self._top_n = top_n

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        # Calculate daily returns
        history = (
            history.with_columns(
                (pl.col("adj_close") / pl.col("adj_close").shift(1) - 1.0).alias("returns")
            )
            .sort("session_date", descending=True)
            .tail(self._window)
        )

        # Calculate cumulative returns
        history = (
            history.with_columns(
                (pl.col("returns").cumsum() * 100).alias("cumulative_returns")
            )
        )

        # Get top N symbols based on highest cumulative returns
        top_symbols = (
            history.select(pl.col("symbol"), pl.col("cumulative_returns"))
            .sort("cumulative_returns", descending=True)
            .head(self._top_n)[["symbol"]]
            .to_dict(False)
            .get(0, [])
        )

        if not top_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(top_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in top_symbols},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
